create or replace function private.schoolpro_cached_family_result_periods() returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_object_agg(q.student_id::text||'|'||q.term||'|'||q.session,true),'{}'::jsonb) from(select distinct r.student_id,r.term,r.session from public.schoolpro_results r where (select private.is_active_account()) and r.student_id=any((select coalesce(array_agg(s.id),array[]::uuid[]) from public.schoolpro_students s where s.user_id=(select auth.uid()) or exists(select 1 from public.schoolpro_guardian_links g where g.student_id=s.id and g.school_id=s.school_id and g.guardian_user_id=(select auth.uid()) and g.status='active'))::uuid[]))q cross join lateral private.schoolpro_result_access(q.student_id,q.term,q.session) access where access.allowed$$;
